CREATE OR REPLACE FUNCTION public.preflight_license_sale(p_tenant uuid,p_kind text,p_code text,p_quantity integer,p_cadence text,p_price numeric,p_start date,p_payment text,p_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t tenants; old license_sales; d pricing_packages; mods text[]; m text; BEGIN
SELECT * INTO t FROM tenants WHERE id=p_tenant AND deleted_at IS NULL; IF NOT FOUND OR NOT (can_portal_write(auth.uid(),'commercial') OR can_manage_partner_billing(t.partner_id)) THEN RAISE EXCEPTION 'Keine Berechtigung'; END IF;
SELECT * INTO old FROM license_sales WHERE request_id=p_request; IF FOUND THEN IF old.tenant_id=p_tenant AND old.product_kind=p_kind AND old.product_code=p_code AND old.quantity=p_quantity AND old.cadence=p_cadence AND old.sale_price=p_price AND old.starts_on=p_start AND old.payment_method=p_payment THEN RETURN old.id; ELSE RAISE EXCEPTION 'Vorgangskennung bereits für andere Verkaufsdaten verwendet'; END IF; END IF;
IF p_kind NOT IN ('module','package','unit') OR p_cadence NOT IN ('once','monthly','quarterly','halfyearly') OR p_payment NOT IN ('invoice','sepa') OR p_quantity IS NULL OR p_quantity<1 OR p_quantity>100000 OR p_price IS NULL OR p_price<0 OR p_price>1000000 OR p_start IS DISTINCT FROM (now() AT TIME ZONE 'Europe/Berlin')::date THEN RAISE EXCEPTION 'Ungültige Verkaufsdaten'; END IF;
IF t.partner_id IS NOT NULL AND EXISTS(SELECT 1 FROM partners WHERE id=t.partner_id AND (NOT is_active OR billing_mode='commission')) THEN RAISE EXCEPTION 'Partner nicht für Wiederverkauf freigeschaltet'; END IF;
IF p_kind<>'unit' AND EXISTS(SELECT 1 FROM license_sales WHERE tenant_id=p_tenant AND product_kind=p_kind AND product_code=p_code AND ended_on IS NULL) THEN RAISE EXCEPTION 'Bereits als Vertrag erfasst'; END IF;
IF p_kind='package' THEN SELECT * INTO d FROM pricing_packages WHERE code=p_code AND active AND NOT always_active; IF NOT FOUND THEN RAISE EXCEPTION 'Paket fehlt'; END IF;
IF EXISTS(SELECT 1 FROM tenant_package_bookings WHERE tenant_id=p_tenant AND package_code=p_code AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Bestehende Paketbuchung unverändert lassen'; END IF;
IF d.requires_package IS NOT NULL AND NOT EXISTS(SELECT 1 FROM license_sales WHERE tenant_id=p_tenant AND product_kind='package' AND product_code=d.requires_package AND ended_on IS NULL) AND NOT EXISTS(SELECT 1 FROM tenant_package_bookings WHERE tenant_id=p_tenant AND package_code=d.requires_package AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Benötigtes Paket fehlt'; END IF;
IF d.requires_any_other AND NOT EXISTS(SELECT 1 FROM license_sales WHERE tenant_id=p_tenant AND product_kind='package' AND ended_on IS NULL) AND NOT EXISTS(SELECT 1 FROM tenant_package_bookings WHERE tenant_id=p_tenant AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Weiteres Paket fehlt'; END IF;
IF EXISTS(SELECT 1 FROM license_sales s JOIN pricing_package_modules pm ON pm.module_code=s.product_code WHERE s.tenant_id=p_tenant AND s.product_kind='module' AND s.ended_on IS NULL AND pm.package_code=p_code) THEN RAISE EXCEPTION 'Bereits einzeln verkaufte Module im Paket'; END IF;
SELECT array_agg(module_code) INTO mods FROM pricing_package_modules WHERE package_code=p_code;
ELSIF p_kind='module' THEN IF NOT EXISTS(SELECT 1 FROM module_prices WHERE module_code=p_code) OR p_code='dashboard' THEN RAISE EXCEPTION 'Modulpreis fehlt'; END IF;
IF EXISTS(SELECT 1 FROM tenant_package_bookings b JOIN pricing_package_modules pm ON pm.package_code=b.package_code WHERE b.tenant_id=p_tenant AND b.cancelled_at IS NULL AND pm.module_code=p_code) OR EXISTS(SELECT 1 FROM license_sales s JOIN pricing_package_modules pm ON pm.package_code=s.product_code WHERE s.tenant_id=p_tenant AND s.product_kind='package' AND s.ended_on IS NULL AND pm.module_code=p_code) THEN RAISE EXCEPTION 'Modul durch Paket abgedeckt'; END IF; mods:=ARRAY[p_code];
ELSE IF p_code NOT IN ('charge_point','extra_location') OR NOT EXISTS(SELECT 1 FROM pricing_unit_prices WHERE code=p_code) THEN RAISE EXCEPTION 'Mengenlizenz fehlt'; END IF; mods:=CASE WHEN p_code='charge_point' THEN ARRAY['ev_charging'] ELSE ARRAY['locations'] END; END IF;
FOREACH m IN ARRAY coalesce(mods,ARRAY[]::text[]) LOOP IF t.partner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM partner_modules WHERE partner_id=t.partner_id AND module_code=m) THEN RAISE EXCEPTION 'Nicht im Partnerportfolio: %',m; END IF; END LOOP;
RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.preflight_license_sale(uuid,text,text,integer,text,numeric,date,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.preflight_license_sale(uuid,text,text,integer,text,numeric,date,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.check_license_sale_preflight() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM preflight_license_sale(NEW.tenant_id,NEW.product_kind,NEW.product_code,NEW.quantity,NEW.cadence,NEW.sale_price,NEW.starts_on,NEW.payment_method,NEW.request_id); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS check_license_sale_preflight ON public.license_sales;
CREATE TRIGGER check_license_sale_preflight BEFORE INSERT ON public.license_sales FOR EACH ROW EXECUTE FUNCTION public.check_license_sale_preflight();
CREATE OR REPLACE FUNCTION public.generate_due_license_invoices() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s license_sales; n integer:=0; k integer; today date:=(now() AT TIME ZONE 'Europe/Berlin')::date; BEGIN FOR s IN SELECT * FROM license_sales WHERE next_period<=today AND ended_on IS NULL ORDER BY next_period LIMIT 200 FOR UPDATE SKIP LOCKED LOOP k:=0; WHILE s.next_period<=today AND k<24 LOOP PERFORM bill_license_sale(s.id,s.next_period,false); n:=n+1;k:=k+1; SELECT * INTO s FROM license_sales WHERE id=s.id; EXIT WHEN s.next_period IS NULL; END LOOP; END LOOP; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.set_partner_invoice_status(p_invoice uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i partner_customer_invoices; BEGIN SELECT * INTO i FROM partner_customer_invoices WHERE id=p_invoice FOR UPDATE; IF NOT FOUND OR NOT can_manage_partner_billing(i.partner_id) OR p_status NOT IN ('paid','voided') THEN RAISE EXCEPTION 'Keine Berechtigung'; END IF; IF p_status='paid' AND i.issued_at IS NULL THEN RAISE EXCEPTION 'Rechnung zuerst freigeben'; END IF; UPDATE partner_customer_invoices SET status=p_status WHERE id=p_invoice; END $$;
REVOKE ALL ON FUNCTION public.set_partner_invoice_status(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_partner_invoice_status(uuid,text) TO authenticated;